function mtInterval(bpm){
  var b=Number(bpm);
  if(!isFinite(b)) b=120;
  b=Math.min(260,Math.max(30,b));
  return 60/b;
}
function mtClampBpm(bpm){ var b=Number(bpm); if(!isFinite(b)) b=120; return Math.min(260,Math.max(30,Math.round(b))); }
function mtAccent(beatIndex, beatsPerBar){
  var bpb=Math.max(1,Math.floor(beatsPerBar)||4);
  var i=((Math.floor(beatIndex)%bpb)+bpb)%bpb;
  return i===0 ? 'strong' : (bpb===6 && i===3 ? 'medium' : 'weak');
}
function mtFreq(accent){ return accent==='strong'?1568:accent==='medium'?1175:880; }
function mtTap(times){
  var ts=(times||[]).slice(-6);
  if(ts.length<2) return null;
  var gaps=[];
  for(var i=1;i<ts.length;i++){
    var g=ts[i]-ts[i-1];
    if(g>0 && g<3000) gaps.push(g);
  }
  if(!gaps.length) return null;
  var avg=gaps.reduce(function(a,b){return a+b;},0)/gaps.length;
  return mtClampBpm(60000/avg);
}
function mtSchedule(nextTime, currentTime, lookahead, interval){
  var out=[];
  var t=nextTime;
  while(t < currentTime + lookahead){ out.push(Math.round(t*1000)/1000); t+=interval; }
  return { beats:out, nextTime:t };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { mtInterval:mtInterval, mtClampBpm:mtClampBpm, mtAccent:mtAccent, mtFreq:mtFreq, mtTap:mtTap, mtSchedule:mtSchedule };
}
if (typeof window !== 'undefined') {
  window.MetronomeForgePure = { mtInterval:mtInterval, mtClampBpm:mtClampBpm, mtAccent:mtAccent, mtFreq:mtFreq, mtTap:mtTap, mtSchedule:mtSchedule };
}
